import{_ as o,l as n,o as e,c as i,v as t,p as l,x as r,d,i as c,S as A}from"./chunks/framework.InCnrqk-.js";const V=JSON.parse('{"title":"时钟门控与 DVFS","description":"","frontmatter":{"title":"时钟门控与 DVFS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/clock-gating-dvfs.md","filePath":"cs/clock-gating-dvfs.md","lastUpdated":1789023840000}'),p={name:"cs/clock-gating-dvfs.md"};function E(h,a,f,F,S,_){const s=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="时钟门控与-dvfs" tabindex="-1">时钟门控与 DVFS <a class="header-anchor" href="#时钟门控与-dvfs" aria-label="Permalink to &quot;时钟门控与 DVFS&quot;">​</a></h1><div class="epigraph"><p>不翻转的寄存器仍被时钟树扇入；门控切断局部时钟。电压与频率一起降，动态功耗按 $V^2f$ 掉，时序预算必须同步改写。</p><footer>—— 据 Hennessy and Patterson, CA:AQA；Weste and Harris, CMOS VLSI Design；Rabaey et al., Digital Integrated Circuits 整理</footer></div><p><a href="/cs/power-dynamic-static">上一课</a>给出 \\(CV^2f\\alpha\\) 与漏电。缺口是两条常用旋钮：<strong>时钟门控</strong>降无效翻转，<strong>DVFS</strong>（动态电压频率调节）降 \\(V\\) 与 \\(f\\)。它们接到 <a href="/cs/clock-skew-cts">CTS</a> 与 <a href="/cs/sta">STA</a>，不是操作系统里随便写一个「省电」标志就结束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>流水线里空泡仍让 FF 每拍采样。门控：用锁存或专用门控单元把时钟与使能相与，使能关掉则该簇 FF 不翻转，时钟缓冲下游也可停。缺口是正确性：门控单元必须避免毛刺时钟，且使能相对时钟满足建立，否则引入假边沿。DVFS：电压岛或整核调 \\(V\\)，频率跟 STA 在该电压下的 \\(f_{\\max}\\)。缺口不是新的功耗公式，而是<strong>控制环</strong>与多角时序。</p><h3 id="门控不是异步复位" tabindex="-1">门控不是异步复位 <a class="header-anchor" href="#门控不是异步复位" aria-label="Permalink to &quot;门控不是异步复位&quot;">​</a></h3><p>关掉时钟不会把状态清零；状态冻住。复位策略仍独立。把 clock enable 当成 reset，上电与休眠唤醒的状态机会错。DVFS 降压时漏电也降，但 SRAM 稳定性有最低电压，FIFO RAM 不能无限降。</p><p><span class="marginnote">CA:AQA 讨论功耗与 DVFS。Weste/Harris 给出门控电路。综合器可自动插入 ICG（integrated clock gating）单元，RTL 用 <code>enable</code> 描述即可。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>RTL：<code>if (en) q &lt;= d;</code> 综合为门控或数据循环 MUX；真门控省时钟电容。层次：细粒度门控面积开销大，粗粒度（整块 FPU）简单。DVFS：查表或硬件环根据负载选 \\((V,f)\\) 对；跨电压域需要电平移位，CDC 仍可能存在（慢时钟与快时钟）。</p>',10)),(e(),l(A,null,{default:r(()=>[c(s,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20EN%5B%22%E4%BD%BF%E8%83%BD%22%5D%20--%3E%20ICG%5B%22%E6%97%B6%E9%92%9F%E9%97%A8%E6%8E%A7%E5%8D%95%E5%85%83%22%5D%0A%20%20ICG%20--%3E%20FF%5B%22%E5%B1%80%E9%83%A8%20FF%20%E5%81%9C%E7%BF%BB%22%5D%0A%20%20VF%5B%22%E7%94%B5%E5%8E%8B%E9%A2%91%E7%8E%87%E5%AF%B9%22%5D%20--%3E%20STA2%5B%22%E8%AF%A5%E8%A7%92%E4%B8%8B%E7%9A%84%20STA%22%5D%0A%20%20FF%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%8A%9F%E8%80%97%E5%A2%99%22%5D%0A%20%20STA2%20--%3E%20LATER%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>测试模式常强制开门控，保证扫描移位——后课 DFT 会再提。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Dennard 缩放下一课解释：过去降压几乎免费跟上频率；墙之后主要靠门控、暗硅与多核。本课先把两个工程旋钮交到设计者手里。异步 FIFO 两端频率可以因 DVFS 独立变，深度与空满仍靠格雷指针，不靠已知相位。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不设计片上稳压器，不写 Linux <code>cpufreq</code> 驱动。不把 GPU 的 SM 级 DVFS 表格抄来。不讨论电池化学。</p><p>后课默认：门控降时钟翻转；DVFS 改 \\(V,f\\) 并重做时序；漏电还要靠阈值与断电。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>门控切断局部时钟，须无毛刺、满足使能时序。</li><li>DVFS 沿 \\(V^2f\\) 下降，受 SRAM 与 STA 约束。</li><li>冻时钟 ≠ 复位。</li><li>出处：Hennessy and Patterson, CA:AQA；Weste and Harris；Rabaey et al.。</li></ul>',8))])}const m=o(p,[["render",E]]);export{V as __pageData,m as default};
